begin;
create table if not exists public.question_reliability_20261004_backup(
 question_id uuid primary key,track_id text not null,before_choices jsonb not null,before_assets jsonb not null,
 before_explanation text not null,before_hash text not null,after_hash text,
 revision_fingerprint text,revision_active boolean,created_at timestamptz not null default now()
);
alter table public.question_reliability_20261004_backup enable row level security;
revoke all on public.question_reliability_20261004_backup from public,anon,authenticated;
grant all on public.question_reliability_20261004_backup to service_role;
do $repair$
declare p jsonb;q public.questions%rowtype;k public.question_keys%rowtype;r public.revision_items%rowtype;h text;
begin
 for p in select value from jsonb_array_elements('[{"id":"33d2a537-4119-55aa-b2d1-43093493525b","track_id":"est2","before_hash":"78c8871d170b52375256d708128fc8e7","revision_fingerprint":null,"revision_active":null,"asset_patch":{},"choices":[{"key":"A","text":"The mean will increase."},{"key":"B","text":"The mean will decrease."},{"key":"C","text":"The mean will remain the same."},{"key":"D","text":"There is not enough information to determine how the mean will change."}],"explanation":"D. There are40 clients. Using the fee intervals, the original total can range from8(170)+11(200)+21(240)=8600 to8(190)+11(230)+21(300)=10350. The original mean can therefore range from215 to258.75. A new fee of250 can be above, below or equal to the old mean, so its effect cannot be determined.","reason":"Remove neighboring heading and add independently worked explanation; preserve key."},{"id":"342cf901-00aa-513f-8924-3521fc0586ab","track_id":"est","before_hash":"795c8555aab4664dd13247206df582f5","revision_fingerprint":null,"revision_active":null,"asset_patch":{},"choices":[{"key":"A","text":"(n, (5/3)n − 8)"},{"key":"B","text":"(−(3/5)n + 8/5, n)"},{"key":"C","text":"(n − 1, (5/3)n − 1)"},{"key":"D","text":"((3/5)n + 1, n − 1)"}],"explanation":"D. Substitute x=(3/5)n+1 and y=n−1: 5x−3y=3n+5−3n+3=8 for every real n. The second equation is −4 times the first, so the same pair satisfies it. A gives24, B gives8−6n, and C gives−2, so they do not work for every n.","reason":"Remove neighboring heading and add independently worked explanation; preserve key."},{"id":"3d35f00b-685a-5120-8b87-413faee86304","track_id":"est","before_hash":"0cb8ac1cd3122cb87aa31daa35fc722d","revision_fingerprint":null,"revision_active":null,"asset_patch":{},"choices":[{"key":"A","text":"Those who have more than one allergy are assigned to the new vaccine."},{"key":"B","text":"The median weight of the patients is found. Those who weigh less than the median weight are assigned to the new vaccine."},{"key":"C","text":"The patients divide themselves evenly into two groups. A coin is tossed to decide which group is assigned to the new vaccine."},{"key":"D","text":"Each patient is given a random number. Those with an even number are assigned to the new vaccine."}],"explanation":"D. Assigning a random number to each patient and using even versus odd numbers assigns patients randomly. The other methods use allergy/weight characteristics or allow patients to choose groups, which does not randomly assign individual patients.","reason":"Remove neighboring heading and add independently worked explanation; preserve key."},{"id":"45681f3d-0ff3-5754-b427-7142165b048b","track_id":"est","before_hash":"61937475d4e680e7d3f1fd1348123c87","revision_fingerprint":null,"revision_active":null,"asset_patch":{},"choices":[{"key":"A","text":"II only"},{"key":"B","text":"III only"},{"key":"C","text":"II and III"},{"key":"D","text":"I, II, and III"}],"explanation":"B, III only. Sorting gives75,83,87,87,90,91,98. Mode=87 and median=87, so I is false. The mean is611/7≈87.286, so II is false. Range=98−75=23>20, so III is true.","reason":"Remove neighboring heading and add independently worked explanation; preserve key."},{"id":"4bbf865e-5279-5547-a289-111ac0501705","track_id":"est2","before_hash":"61937475d4e680e7d3f1fd1348123c87","revision_fingerprint":null,"revision_active":null,"asset_patch":{},"choices":[{"key":"A","text":"II only"},{"key":"B","text":"III only"},{"key":"C","text":"II and III"},{"key":"D","text":"I, II, and III"}],"explanation":"B, III only. Sorting gives75,83,87,87,90,91,98. Mode=87 and median=87, so I is false. The mean is611/7≈87.286, so II is false. Range=98−75=23>20, so III is true.","reason":"Remove neighboring heading and add independently worked explanation; preserve key."},{"id":"610e9cea-478f-5411-a242-0213bcd11419","track_id":"est","before_hash":"6761f407082fe9658bcaadb3fe6c5c5d","revision_fingerprint":null,"revision_active":null,"asset_patch":{},"choices":[{"key":"A","text":"9/50"},{"key":"B","text":"3/10"},{"key":"C","text":"3/7"},{"key":"D","text":"9/20"}],"explanation":"B. The probability of neither vanilla nor coffee is100%−28%−12%=60%. Cookies and cream is18%, so the conditional probability is18/60=3/10.","reason":"Remove neighboring heading and add independently worked explanation; preserve key."},{"id":"6408786d-26bf-5e10-8c18-20ffaeb9add2","track_id":"est2","before_hash":"6761f407082fe9658bcaadb3fe6c5c5d","revision_fingerprint":null,"revision_active":null,"asset_patch":{},"choices":[{"key":"A","text":"9/50"},{"key":"B","text":"3/10"},{"key":"C","text":"3/7"},{"key":"D","text":"9/20"}],"explanation":"B. The probability of neither vanilla nor coffee is100%−28%−12%=60%. Cookies and cream is18%, so the conditional probability is18/60=3/10.","reason":"Remove neighboring heading and add independently worked explanation; preserve key."},{"id":"7a32c914-e960-57fa-ae87-1da1974649de","track_id":"sat","before_hash":"1fc3274c374f5d9b2e15fe74fd156ce9","revision_fingerprint":"8531f676ac7ecf0a80fade0399be801d","revision_active":true,"asset_patch":{"figure":"https://math.portal.ghoneem.com/assets/question-figures/elite-m2-q21-20261004.png","source_image_sha256":"305acda582ccdf1ed0fcbd7c134f45eb3a2031011c71902036babbdcd232a53f","figure_caption":"Original scatterplot restored from source page97","graph_review_20261004":{"status":"verified","source_pages":[97,98],"method":"Opaque source-PDF rendering and independent regression influence check"}},"explanation":"C, I and II. The point(0,12) lies far above the remaining points near the center. Including it raises the fitted curve at x=0 and flattens the curvature. Removing it lowers the y-intercept, so c<6.52, and makes the upward curvature larger, so a>0.04. Both statements hold. This was checked against source pages97–98; a regression influence calculation with conservative intervals for the plotted x-positions confirms both directions.","reason":"Recover unreadable source graph, independently verify C, and add worked explanation."},{"id":"7b82313c-b9a2-5fac-be19-c29993859954","track_id":"est2","before_hash":"0cb8ac1cd3122cb87aa31daa35fc722d","revision_fingerprint":null,"revision_active":null,"asset_patch":{},"choices":[{"key":"A","text":"Those who have more than one allergy are assigned to the new vaccine."},{"key":"B","text":"The median weight of the patients is found. Those who weigh less than the median weight are assigned to the new vaccine."},{"key":"C","text":"The patients divide themselves evenly into two groups. A coin is tossed to decide which group is assigned to the new vaccine."},{"key":"D","text":"Each patient is given a random number. Those with an even number are assigned to the new vaccine."}],"explanation":"D. Assigning a random number to each patient and using even versus odd numbers assigns patients randomly. The other methods use allergy/weight characteristics or allow patients to choose groups, which does not randomly assign individual patients.","reason":"Remove neighboring heading and add independently worked explanation; preserve key."},{"id":"93bff759-c958-5628-8a62-52d2298e39dd","track_id":"sat","before_hash":"eb704ba93685dc0a9b6615dd7436e4d2","revision_fingerprint":"5816b215afac0b25022490895dff2668","revision_active":false,"asset_patch":{},"explanation":"D. The original weighted total is25×8+40×2+45×4+55×10+70×6=1430 over30 prices, so the mean is1430/30≈47.67. Removing one25 gives1405/29≈48.45, which is larger. The original15th and16th prices are both55; after removing the25, the new15th price is still55. Thus the mean increases and the median remains the same.","reason":"Add worked solution verified against attached frequency table; preserve D."},{"id":"c67b0e13-af43-5f72-9910-ca0da3a09ae9","track_id":"est","before_hash":"78c8871d170b52375256d708128fc8e7","revision_fingerprint":null,"revision_active":null,"asset_patch":{},"choices":[{"key":"A","text":"The mean will increase."},{"key":"B","text":"The mean will decrease."},{"key":"C","text":"The mean will remain the same."},{"key":"D","text":"There is not enough information to determine how the mean will change."}],"explanation":"D. There are40 clients. Using the fee intervals, the original total can range from8(170)+11(200)+21(240)=8600 to8(190)+11(230)+21(300)=10350. The original mean can therefore range from215 to258.75. A new fee of250 can be above, below or equal to the old mean, so its effect cannot be determined.","reason":"Remove neighboring heading and add independently worked explanation; preserve key."},{"id":"ed24df84-a49d-51c0-8d98-40dd1ccedde0","track_id":"est2","before_hash":"795c8555aab4664dd13247206df582f5","revision_fingerprint":null,"revision_active":null,"asset_patch":{},"choices":[{"key":"A","text":"(n, (5/3)n − 8)"},{"key":"B","text":"(−(3/5)n + 8/5, n)"},{"key":"C","text":"(n − 1, (5/3)n − 1)"},{"key":"D","text":"((3/5)n + 1, n − 1)"}],"explanation":"D. Substitute x=(3/5)n+1 and y=n−1: 5x−3y=3n+5−3n+3=8 for every real n. The second equation is −4 times the first, so the same pair satisfies it. A gives24, B gives8−6n, and C gives−2, so they do not work for every n.","reason":"Remove neighboring heading and add independently worked explanation; preserve key."}]'::jsonb) loop
  select * into q from public.questions where id=(p->>'id')::uuid for update;
  select * into k from public.question_keys where question_id=q.id for update;
  if q.id is null or q.track_id is distinct from p->>'track_id' or k.question_id is null
   or md5(jsonb_build_array(q.stem,q.choices,q.assets,k.correct,k.explanation)::text) is distinct from p->>'before_hash'
   then raise exception 'Concurrent content change: %',p->>'id'; end if;
  select * into r from public.revision_items where question_id=q.id for update;
  if r.fingerprint is distinct from p->>'revision_fingerprint' or r.active is distinct from (p->>'revision_active')::boolean then raise exception 'Concurrent revision change: %',q.id; end if;
  insert into public.question_reliability_20261004_backup(question_id,track_id,before_choices,before_assets,before_explanation,before_hash,revision_fingerprint,revision_active)
   values(q.id,q.track_id,q.choices,q.assets,k.explanation,p->>'before_hash',r.fingerprint,r.active);
  update public.questions set choices=coalesce(p->'choices',choices),assets=assets||(p->'asset_patch') where id=q.id;
  update public.question_keys set explanation=coalesce(p->>'explanation',explanation) where question_id=q.id;
  select md5(jsonb_build_array(q2.stem,q2.choices,q2.assets,k2.correct,k2.explanation)::text),public.revision_question_fingerprint(q2.stem,q2.choices,q2.assets,k2.correct,k2.explanation)
   into h,r.fingerprint from public.questions q2 join public.question_keys k2 on k2.question_id=q2.id where q2.id=q.id;
  update public.question_reliability_20261004_backup set after_hash=h where question_id=q.id;
  if r.question_id is not null then update public.revision_items set fingerprint=r.fingerprint,active=case when p->'asset_patch' ? 'release_hold_reason' then false else active end where question_id=q.id; end if;
  insert into public.audit_log(action,target_type,target_id,meta) values('question.reliability_20261004','question',q.id::text,jsonb_build_object('track_id',q.track_id,'reason',p->>'reason','before_hash',p->>'before_hash','after_hash',h));
 end loop;
end $repair$;
commit;
